-- Faculty and classes, generated by: python -m scheduler web
begin;
on conflict (key) do update set name = excluded.name, college = excluded.college, department = excluded.department, rank = excluded.rank, designation = excluded.designation, max_lu = excluded.max_lu;
on conflict (id) do update set course = excluded.course, section = excluded.section, program = excluded.program, college = excluded.college, department = excluded.department, is_ge = excluded.is_ge, plan_teacher = excluded.plan_teacher, holder_dept = excluded.holder_dept, holder_college = excluded.holder_college, house_dept = excluded.house_dept, house_college = excluded.house_college;
commit;
